6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n6:[\"$\",\"$L22\",null,{\"pageId\":1365,\"activeView\":{\"name\":\"default\",\"activeViewSuffix\":\"\",\"language\":\"en\"},\"children\":\"$@23\"}]\n9:null\ne:[[\"$\",\"title\",\"0\",{\"children\":\"Bhagavad-gītā As It Is 4.13\"}],[\"$\",\"meta\",\"1\",{\"name\":\"description\",\"content\":\"Srila Prabhupada''s books online\"}],[\"$\",\"meta\",\"2\",{\"name\":\"application-name\",\"content\":\"Vedabase\"}],[\"$\",\"link\",\"3\",{\"rel\":\"author\",\"href\":\"https://vedabase.io\"}],[\"$\",\"meta\",\"4\",{\"name\":\"author\",\"content\":\"A.C. Bhaktivedanta Swami - Srila Prabhupada\"}],[\"$\",\"meta\",\"5\",{\"name\":\"keywords\",\"content\":\"Srila Prabhupada,Krsna,Krishna,bhakti,devotion\"}],[\"$\",\"meta\",\"6\",{\"name\":\"creator\",\"content\":\"Prahlad Nrsimha das\"}]]\n"])self.__next_f.push([1,"25:T8e7,"])self.__next_f.push([1,"The Lord is the creator of everything. Everything is born of Him, everything is sustained by Him, and everything, after annihilation, rests in Him. He is therefore the creator of the four divisions of the social order, beginning with the intelligent class of men, technically called brāhmaṇas due to their being situated in the mode of goodness. Next is the administrative class, technically called the kṣatriyas due to their being situated in the mode of passion. The mercantile men, called the vaiśyas, are situated in the mixed modes of passion and ignorance, and the śūdras, or laborer class, are situated in the ignorant mode of material nature. In spite of His creating the four divisions of human society, Lord Kṛṣṇa does not belong to any of these divisions, because He is not one of the conditioned souls, a section of whom form human society. Human society is similar to any other animal society, but to elevate men from the animal status, the above-mentioned divisions are created by the Lord for the systematic development of Kṛṣṇa consciousness. The tendency of a particular man toward work is determined by the modes of material nature which he has acquired. Such symptoms of life, according to the different modes of material nature, are described in the Eighteenth Chapter of this book. A person in Kṛṣṇa consciousness, however, is above even the brāhmaṇas. Although brāhmaṇas by quality are supposed to know about Brahman, the Supreme Absolute Truth, most of them approach only the impersonal Brahman manifestation of Lord Kṛṣṇa. But a man who transcends the limited knowledge of a brāhmaṇa and reaches the knowledge of the Supreme Personality of Godhead, Lord Śrī Kṛṣṇa, becomes a person in Kṛṣṇa consciousness – or, in other words, a Vaiṣṇava. Kṛṣṇa consciousness includes knowledge of all different plenary expansions of Kṛṣṇa, namely Rāma, Nṛsiṁha, Varāha, etc. And as Kṛṣṇa is transcendental to this system of the four divisions of human society, a person in Kṛṣṇa consciousness is also transcendental to all divisions of human society, whether we consider the divisions of community, nation or species."])self.__next_f.push([1,"23:[\"$\",\"div\",null,{\"className\":\"flex flex-col min-h-screen text-vb-normal-text\",\"children\":[[\"$\",\"$L1a\",null,{\"className\":\"w-full left-0 z-30 bg-vb-body/95\",\"children\":[\"$\",\"$L1b\",null,{\"mainMenu\":\"$L24\",\"page\":{\"id\":1365,\"meta\":{\"type\":\"books.Verse\",\"slug\":\"13\",\"show_in_menus\":false,\"seo_title\":\"\",\"search_description\":\"\",\"first_published_at\":null,\"alias_of\":null,\"locale\":\"en\"},\"title\":\"TEXT 13\",\"advanced_view_url_path\":\"/en/library/bg/4/advanced-view/#bb1216\",\"language_menu\":[{\"display_name\":\"አማርኛ (Ethiopian)\",\"language_code\":\"am\",\"enabled\":false,\"url_path\":\"/am/\"},{\"display_name\":\